CREATE POLICY "payment_qr_admin_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'payment-qr' AND private.has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "payment_qr_admin_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'payment-qr' AND private.has_role(auth.uid(), 'admin'::app_role)) WITH CHECK (bucket_id = 'payment-qr' AND private.has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "payment_qr_admin_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'payment-qr' AND private.has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "payment_qr_authenticated_read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'payment-qr');